TEST_PASSWORD = "Starter-test-1"


def png(width=156, height=70, rgb=(37, 99, 235)):
    """A valid solid-color PNG built with the standard library (stands in for the real illustrations)."""
    raw = b"".join(b"\x00" + bytes(rgb) * width for _ in range(height))

    def chunk(kind, data):
        return struct.pack(">I", len(data)) + kind + data + struct.pack(">I", zlib.crc32(kind + data) & 0xffffffff)
    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", width, height, 8, 2, 0, 0, 0))
            + chunk(b"IDAT", zlib.compress(raw)) + chunk(b"IEND", b""))


def image_keys(html):
    return sorted(set(re.findall(r"\{(fig-[a-z-]+)\}", html)))


def publish_starter_content(base_url, db_path, password=TEST_PASSWORD):
    """
    Creates the five authors in db_path and publishes their materials through the server at base_url:
    each author uploads images, submits a publication and a question; both are approved through
    backend.db.update_submission_status. Returns one dict per author with ids and submission ids.
    """
    import sqlite3

    from backend.db import update_submission_status
    from backend.users import create_user
    from tests.http_client import Client

    def upload(client, key):
        data = "data:image/png;base64," + base64.b64encode(png(rgb=(40 + len(key) * 7 % 200, 99, 235))).decode()
        status, body = client.request("POST", "/api/media/upload", {"image": data})
        assert status == 200 and body.get("success"), (key, status, body)
        return body["url"]

    def submit(client, draft, title, html, settings, kind):
        payload = {"draftId": draft, "title": title, "html": html,
                   "publicationSettings": dict(settings, materialType=kind, type=kind)}
        status, body = client.request("POST", "/api/moderation/submit", payload)
        assert status == 200 and body.get("success"), (title, status, body)
        assert update_submission_status(body["submissionId"], "approved", db_path=db_path)
        return body["submissionId"]

    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    result = []
    try:
        for a in AUTHORS:
            user = create_user(conn, a["login"], a["email"], password, email_verified=True)
            name = a["first_name"] + " " + a["last_name"]
            with conn:
                conn.execute("""INSERT OR REPLACE INTO user_profiles
                                (user_id, name, first_name, last_name, specialization, company, bio, created_at, updated_at)
                                VALUES (?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))""",
                             (user["id"], name, a["first_name"], a["last_name"], a["specialization"], a["company"], a["bio"]))
                conn.execute("UPDATE users SET name = ? WHERE id = ?", (name, user["id"]))
            result.append({"id": user["id"], "name": name, "login": a["login"], "email": a["email"]})
    finally:
        conn.close()

    for a, info in zip(AUTHORS, result):
        client = Client(base_url).login(a["login"], password)
        pub = a["publication"]
        html = pub["html"]
        for key in image_keys(html):
            html = html.replace("{" + key + "}", upload(client, key))
        settings = dict(pub["settings"], coverImage=upload(client, pub["cover"]))
        info["publication"] = submit(client, pub["draft"], pub["title"], html, settings, "publication")
        q = a["question"]
        info["question"] = submit(client, q["draft"], q["title"], q["html"], q["settings"], "question")
    return result
